import type { ViewTransitionClass } from 'react'

/**
 * `view-transition-class` values that map to the animations in `app/globals.css`.
 * Keys are the transition types tagged on `<Link transitionTypes={[...]}>`;
 * `default` covers transitions that carry no type (browser back/forward,
 * `router.refresh()`, and Suspense reveals).
 */

/** Directional page slide: content moves left going deeper, right coming back. */
export const navDirection: ViewTransitionClass = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

/**
 * Suspense fallback leaving. Scoped to untyped transitions so the skeleton
 * handoff never stacks a vertical slide on top of a directional page slide.
 */
export const revealExit: ViewTransitionClass = {
  'nav-forward': 'none',
  'nav-back': 'none',
  default: 'slide-down',
}

/** Suspense content arriving. Counterpart to {@link revealExit}. */
export const revealEnter: ViewTransitionClass = {
  'nav-forward': 'none',
  'nav-back': 'none',
  default: 'slide-up',
}

/**
 * Shared identity for a product's image. The grid thumbnail and the detail hero
 * use the same name so the browser morphs one into the other across routes.
 */
export function productImageName(slug: string) {
  return `product-image-${slug}`
}

