import { Suspense, ViewTransition } from 'react'
import { ProductGrid } from './ProductGrid'
import { ProductGridSkeleton } from './ProductSkeleton'
import { navDirection, revealEnter, revealExit } from '@/lib/view-transitions'

export default function Home() {
  return (
    // The directional wrapper lives in the page, not the layout: layouts persist
    // across navigation, so their enter/exit animations never fire.
    <ViewTransition enter={navDirection} exit={navDirection} default="none">
      <main>
        <h1>Products</h1>
        <Suspense
          fallback={
            <ViewTransition exit={revealExit} default="none">
              <ProductGridSkeleton />
            </ViewTransition>
          }
        >
          <ViewTransition enter={revealEnter} default="none">
            <ProductGrid />
          </ViewTransition>
        </Suspense>
      </main>
    </ViewTransition>
  )
}

