@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ==========================================================================
   View transitions
   ========================================================================== */

:root {
  /* Old content leaves fast so it stops competing for attention; new content
     arrives more gently, and movement outlasts the fade. */
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay would otherwise swallow clicks mid-animation. */
::view-transition {
  pointer-events: none;
}

/* --- Shared element: grid thumbnail <-> detail hero ---------------------- */

::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}

/* A touch of blur mid-flight hides pixel interpolation artifacts. */
::view-transition-image-pair(.morph) {
  animation: var(--duration-move) both via-blur;
}

@keyframes via-blur {
  30% {
    filter: blur(3px);
  }
}

/* --- Suspense reveal: skeleton hands off to content ---------------------- */

::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}

::view-transition-new(.slide-up) {
  animation:
    var(--duration-enter) ease-in var(--duration-exit) both fade,
    var(--duration-move) ease-in both slide-y;
}

@keyframes fade {
  from {
    filter: blur(3px);
    opacity: 0;
  }
  to {
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide-y {
  from {
